// src/components/pages/Interview.js
import React, { useRef, useState } from "react";
import { motion } from "framer-motion";
import PageWrapper from "../PageWrapper";

const Interview = () => {
  const videoRef = useRef(null);
  const [recording, setRecording] = useState(false);
  const [videoURL, setVideoURL] = useState(null);

  // Start/Stop recording (simplified for UI)
  const handleRecord = () => {
    if (!recording) {
      setRecording(true);
      // TODO: integrate MediaRecorder / Webcam capture
    } else {
      setRecording(false);
      // TODO: save video and generate URL
      setVideoURL("https://via.placeholder.com/400x300?text=Recorded+Video");
    }
  };

  return (
    <PageWrapper>
      <div className="flex flex-col md:flex-row min-h-screen px-6 py-12 gap-8 bg-gray-50">
        
        {/* Left: Instructions / Question */}
        <motion.div
          initial={{ x: -40, opacity: 0 }}
          animate={{ x: 0, opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="md:w-1/2 bg-white rounded-3xl shadow-xl p-10 flex flex-col justify-between"
        >
          <h2 className="text-3xl font-bold text-black mb-6">Your Interview Question</h2>
          <p className="text-gray-700 text-lg mb-8">
            Please answer the following question as if you were in a real interview.
            Try to speak clearly and confidently.
          </p>
          <p className="text-indigo-600 font-semibold text-xl">
            Example Question: Tell me about a time you solved a difficult problem at work.
          </p>
        </motion.div>

        {/* Right: Video / Record */}
        <motion.div
          initial={{ x: 40, opacity: 0 }}
          animate={{ x: 0, opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="md:w-1/2 bg-white rounded-3xl shadow-xl p-10 flex flex-col items-center justify-center"
        >
          {/* Video Preview */}
          <video
            ref={videoRef}
            src={videoURL || ""}
            autoPlay
            controls
            className="w-full h-64 md:h-80 rounded-xl mb-6 object-cover bg-gray-200"
          >
            Your browser does not support the video tag.
          </video>

          {/* Record Button */}
          <button
            onClick={handleRecord}
            className={`w-48 py-4 rounded-full font-semibold text-white transition-all duration-300 ${
              recording ? "bg-red-600 hover:bg-red-700" : "bg-black hover:bg-gray-900"
            } shadow-lg`}
          >
            {recording ? "Stop Recording" : "Start Recording"}
          </button>
        </motion.div>
      </div>
    </PageWrapper>
  );
};

export default Interview;
